import React, { useState, useEffect } from 'react';
import './App.css'; // CSS dosyanızın aynı klasörde olduğundan emin olun

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); // Başlangıç değeri boş dizi []
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  // 1. Verileri Backend'den Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => {
        console.log("Gelen Veriler:", data);
        // Verinin dizi (array) olup olmadığını kontrol et (Güvenlik önlemi)
        setMekanlar(Array.isArray(data) ? data : []);
      })
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  // 2. FAVORİ EKLEME/ÇIKARMA (Hata Çözen Kısım)
  const favoriEkleCikar = (mekan) => {
    setFavoriler((prev) => {
      // Güvenlik: prev undefined ise boş dizi yap
      const aktifListe = Array.isArray(prev) ? prev : [];

      // Mekan listede var mı?
      const varMi = aktifListe.some(f => f.id === mekan.id);

      if (varMi) {
        // Varsa çıkar: filter yeni bir dizi döndürür, sorun yok
        return aktifListe.filter(f => f.id !== mekan.id);
      } else {
        // Yoksa ekle: spread operatörü (...) ile diziyi kopyala ve yenisini ekle
        // push() KULLANMIYORUZ, çünkü push dizinin yeni uzunluğunu (sayı) döndürür ve hata verir.
        return [...aktifListe, { ...mekan, sure: Number(mekan.sure) || 0 }];
      }
    });
  };

  // 3. Toplam Süre Hesabı
  // favoriler undefined ise reduce patlar, o yüzden (favoriler || []) kullanıyoruz
  const toplamSure = (favoriler || []).reduce((toplam, m) => {
    return toplam + (Number(m.sure) || 0); 
  }, 0);

  // 4. Kategori Renkleri
  const getKategoriRenk = (kat) => {
    switch(kat) {
      case 'Tarih': return '#d35400';
      case 'Doğa': return '#27ae60';
      case 'Yemek': return '#c0392b';
      default: return '#3498db';
    }
  };

  // 5. Filtreleme Mantığı
  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (Number(m.sure) || 0) <= Number(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      {/* Başlık */}
      <div className="header">
        <h1>🌴 Antalya Rota Asistanı</h1>
        <p>Gezmek istediğin yerleri seç, süreyi hesaplayalım.</p>
      </div>

      {/* Kontrol Paneli */}
      <div className="controls">
        <input 
          type="number" 
          className="search-input"
          placeholder="Maksimum Süre (dk)" 
          value={maxSure} 
          onChange={(e) => setMaxSure(e.target.value)} 
        />

        {['Hepsi', 'Tarih', 'Doğa', 'Yemek'].map(k => (
          <button 
            key={k} 
            className={`filter-btn ${filtre === k ? 'active' : ''}`}
            onClick={() => setFiltre(k)}
          >
            {k}
          </button>
        ))}
      </div>

      {/* Rota Özeti (Sarı Bar) */}
      {favoriler.length > 0 && (
        <div className="summary-bar">
          <div className="summary-item">
            <span className="summary-value">{favoriler.length}</span>
            <span className="summary-label">Seçilen Mekan</span>
          </div>
          <div className="summary-item">
            <span className="summary-value">
              {Math.floor(toplamSure / 60) > 0 ? `${Math.floor(toplamSure / 60)} sa ` : ''} 
              {toplamSure % 60} dk
            </span>
            <span className="summary-label">Toplam Süre</span>
          </div>
          <div className="summary-item">
            <span className="summary-value">🎒</span>
            <span className="summary-label">Rotanız Hazır!</span>
          </div>
        </div>
      )}

      {/* Kartlar */}
      <div className="grid">
        {filtrelenmis.map(m => {
          // Kart seçili mi kontrolü (liste boşsa hata vermesin diye ?. operatörü)
          const seciliMi = favoriler?.some(f => f.id === m.id);

          return (
            <div key={m.id} className="card" style={{ border: seciliMi ? '2px solid #ff8c00' : 'none', transform: seciliMi ? 'scale(1.02)' : 'scale(1)' }}>
              <div className="card-image-container">
                <img src={m.resim} alt={m.ad} className="card-img" />
                <span className="badge" style={{ backgroundColor: getKategoriRenk(m.kategori) }}>
                  {m.kategori}
                </span>
              </div>

              <div className="card-content">
                <h3 className="card-title">{m.ad}</h3>
                <div className="card-info">
                  <span>📍 {m.bolge}</span>
                  <span>⏳ {m.sure} dk</span>
                </div>

                <button 
                  onClick={() => favoriEkleCikar(m)}
                  className={`btn-action ${seciliMi ? 'btn-remove' : 'btn-add'}`}
                >
                  {seciliMi ? (
                    <><span>❌</span> Çıkar</>
                  ) : (
                    <><span>🧡</span> Ekle</>
                  )}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default App;
